fn route(line: &str) -> (&'static str, &'static str) {
    if line == "GET / HTTP/1.1" {
        ("200 OK", "欢迎")
    } else {
        ("404 Not Found", "页面不存在")
    }
}
fn main() {
    for line in ["GET / HTTP/1.1", "GET /missing HTTP/1.1"].iter() {
        let (status, body) = route(line);
        println!("{} | {}", status, body);
    }
}

fn response(found: bool) -> String {
    let (status, body) = if found {
        ("200 OK", "首页")
    } else {
        ("404 Not Found", "未找到")
    };
    format!("HTTP/1.1 {}\r\nContent-Length: {}\r\n\r\n{}", status, body.len(), body)
}
fn main() { println!("{}", response(false)); }

