use std::sync::{mpsc, Arc, Mutex};
use std::thread;
type Job = Box<dyn FnOnce() + Send + 'static>;
struct Pool { tx: mpsc::Sender<Job>, workers: Vec<thread::JoinHandle<()>> }
impl Pool {
    fn new(size: usize) -> Self {
        assert!(size > 0);
        let (tx, rx) = mpsc::channel::<Job>();
        let shared = Arc::new(Mutex::new(rx));
        let workers = (0..size).map(|_| {
            let rx = Arc::clone(&shared);
            thread::spawn(move || loop {
                let next = { rx.lock().unwrap().recv() };
                match next { Ok(job) => job(), Err(_) => break }
            })
        }).collect();
        Self { tx, workers }
    }
    fn execute<F: FnOnce() + Send + 'static>(&self, task: F) {
        self.tx.send(Box::new(task)).unwrap();
    }
    fn finish(self) {
        drop(self.tx);
        for worker in self.workers { worker.join().unwrap(); }
    }
}
fn main() {
    let pool = Pool::new(2);
    pool.execute(|| println!("任务甲"));
    pool.execute(|| println!("任务乙"));
    pool.finish();
}

use std::thread::{self, JoinHandle};
struct Worker { handle: Option<JoinHandle<()>> }
impl Drop for Worker {
    fn drop(&mut self) {
        if let Some(handle) = self.handle.take() {
            let _result = handle.join();
        }
