use std::sync::{mpsc, Arc, Mutex};
use std::thread::{self, JoinHandle};
type Job = Box<dyn FnOnce() + Send + 'static>;
enum Message { Run(Job), Stop }
struct Pool { tx: mpsc::Sender<Message>, workers: Vec<Option<JoinHandle<()>>> }
impl Pool {
    fn new(size: usize) -> Self {
        assert!(size > 0);
        let (tx, rx) = mpsc::channel::<Message>();
        let rx = Arc::new(Mutex::new(rx));
        let workers = (0..size).map(|_| {
            let rx = Arc::clone(&rx);
            Some(thread::spawn(move || loop {
                let message = { rx.lock().unwrap().recv() };
                match message {
                    Ok(Message::Run(job)) => job(),
                    Ok(Message::Stop) | Err(_) => break,
                }
            }))
        }).collect();
        Self { tx, workers }
    }
    fn execute<F: FnOnce() + Send + 'static>(&self, job: F) {
        self.tx.send(Message::Run(Box::new(job))).unwrap();
    }
}
impl Drop for Pool {
    fn drop(&mut self) {
        for _ in &self.workers { let _ = self.tx.send(Message::Stop); }
        for slot in &mut self.workers {
            if let Some(handle) = slot.take() { let _ = handle.join(); }
        }
    }
}
fn main() {
    let pool = Pool::new(2);
    pool.execute(|| println!("完成后再退出"));
}
